const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laSerena = ee.Geometry.Point([-71.2504, -29.9045]); // La Serena, Chile
  const targetYear = 2022; // Using 2022 as the "current" year for the deficit calculation
  const startDay = '01-01';
  const endDay = '07-07';
  const scale = 5566; // CHIRPS original scale is ~5.5km, use this or larger for reduceRegion.

  // 2. Data Acquisition & Check - CHIRPS Daily Precipitation
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // Function to calculate year-to-date precipitation for a given year
  const getYTDPrecipitation = (year, geometry) => {
    const startDate = ee.Date.fromYMD(year, 1, 1);
    const endDate = ee.Date.fromYMD(year, 7, 7); // July 7
    const collection = chirps.filterDate(startDate, endDate)
                             .filterBounds(geometry);

    if (collection.size().getInfo() === 0) {
      console.log(`No CHIRPS data found for year ${year} (${startDate.format('YYYY-MM-dd').getInfo()} to ${endDate.format('YYYY-MM-dd').getInfo()}).`);
      return null;
    }

    const ytdPrecipitation = collection.sum(); // Sum daily precipitation
    return ytdPrecipitation;
  };

  // --- Calculate target year (2022) YTD rainfall ---
  const currentYearPrecipImage = getYTDPrecipitation(targetYear, laSerena);

  if (currentYearPrecipImage === null) {
    console.log("Failed to retrieve current year precipitation image.");
    console.log("C1"); // Empty Collection
    return;
  }

  const currentYearPrecip = await currentYearPrecipImage.reduceRegion({
    reducer: ee.Reducer.sum(), // Summing values over a point just gets the value at that point
    geometry: laSerena,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  if (currentYearPrecip === null || typeof currentYearPrecip === 'undefined') {
    console.log(`Calculation failure for current year (${targetYear}) precipitation.`);
    console.log("C3");
    return;
  }

  const currentYearPixels = await currentYearPrecipImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: laSerena,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  if (currentYearPixels === 0) {
    console.log("No valid pixels for current year precipitation after reduction.");
    console.log("C2");
    return;
  }

  // --- Calculate mean YTD rainfall for 1990-2020 ---
  const annualPrecipitations = [];
  for (let year = 1990; year <= 2020; year++) {
    const precipImage = getYTDPrecipitation(year, laSerena);
    if (precipImage === null) {
      // Allow for some missing years, but warn. If too many, might indicate C1.
      console.log(`Warning: Skipping year ${year} due to missing data.`);
      continue;
    }

    const precip = await precipImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: laSerena,
      scale: scale,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

    const pixels = await precipImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: laSerena,
      scale: scale,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

    if (pixels === 0) {
      console.log(`Warning: No valid pixels for year ${year} after reduction. Skipping.`);
      continue;
    }

    if (precip !== null && typeof precip !== 'undefined') {
      annualPrecipitations.push(precip);
    } else {
      console.log(`Warning: Calculation failure for year ${year} precipitation. Skipping.`);
    }
  }

  if (annualPrecipitations.length === 0) {
    console.log("No valid annual precipitation totals for the reference period (1990-2020).");
    console.log("C1"); // Or C2 if images existed but all had 0 pixels
    return;
  }

  const meanPrecipitation = annualPrecipitations.reduce((a, b) => a + b, 0) / annualPrecipitations.length;

  if (meanPrecipitation === 0) {
      console.log("Mean precipitation for the reference period is zero. Cannot calculate deficit.");
      console.log("C3");
      return;
  }

  // 4. Calculation - Deficit
  const deficit = ((meanPrecipitation - currentYearPrecip) / meanPrecipitation) * 100;

  // 5. Validation & Final Answer
  console.log(`La Serena (2022 Jan 1 - Jul 7) Rainfall: ${currentYearPrecip.toFixed(2)} mm`);
  console.log(`La Serena (1990-2020 Mean Jan 1 - Jul 7) Rainfall: ${meanPrecipitation.toFixed(2)} mm (from ${annualPrecipitations.length} years)`);
  console.log(`Deficit: ${deficit.toFixed(2)} %`);

  if (currentYearPrecip === null || meanPrecipitation === null || isNaN(deficit)) {
    console.log("C3"); // Calculation failure
  } else if (deficit > 40) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
